    "sensor_positions": [
      {"x": -0.04, "y": 0.06},
      {"x": -0.02, "y": 0.06},
      {"x": 0.0, "y": 0.06},
      {"x": 0.02, "y": 0.06},
      {"x": 0.04, "y": 0.06}
    ],
    "sensor_size": 0.012,
