  },
  "controller": {
    "base_speed": 1.3,
    "kp": 3.5,
    "ki": 0.0,
    "kd": 0.6,
    "sensor_weights": [-2.0, -1.0, 0.0, 1.0, 2.0],
    "line_loss": "last_direction"
  },
  "observation_request": {
    "measurements": [
      "completion",
      "progress",
      "completion_time",
      "rms_error",
      "max_error",
      "line_loss_events",
      "steering_oscillation",
      "control_effort",
      "controller_errors",
      "noise_robustness"
    ]
  },
  "_presentation": {
    "entity0": {
      "label": "Wider sensor span 0.04m",
      "notes": "Widens the sensor array from ±0.03 m to ±0.04 m to keep tape under a sensor when the robot drifts, targeting slalom and s-bend line losses. Controller is unchanged from iteration 1 (kp 3.5, kd 0.6, base 1.3) to isolate the geometry effect, which iteration 1 showed was still failing with about 1 line loss per run."
    }
  }
